import{_ as e,o as c,c as r,a5 as t}from"./chunks/framework.DJo0M80U.js";const m=JSON.parse('{"title":"IoC 的概念和作用","description":"","frontmatter":{"title":"IoC 的概念和作用","date":"2026-07-03T00:00:00.000Z","categories":["Java 快速入门"],"tags":["Java","Spring","OneNote"],"lastUpdated":false},"headers":[],"relativePath":"posts/java快速入门/第六部分：Spring 生态/01-Spring 核心/IoC 的概念和作用.md","filePath":"posts/java快速入门/第六部分：Spring 生态/01-Spring 核心/IoC 的概念和作用.md"}'),d={name:"posts/java快速入门/第六部分：Spring 生态/01-Spring 核心/IoC 的概念和作用.md"};function p(a,o,s,n,i,l){return c(),r("div",null,[...o[0]||(o[0]=[t('<div><p><strong>什么是程序的耦合</strong> 耦合性<code>(Coupling)</code>，也叫耦合度，是对模块间关联程度的度量。耦合的强弱取决于模块间接口的复杂性、调用模块的方式以及通过界面传送数据的多少。模块间的耦合度是指模块之间的依赖关系，包括控制关系、调用关系、数据传递关系。模块间联系越多，其耦合性越强，同时表明其独立性越差<code>(</code> 降低耦合性，可以提高其独立性<code>)</code>。耦合性存在于各个领域，而非软件设计中独有的，但是我们只讨论软件工程中的耦合。</p><p>在软件工程中，耦合指的就是就是对象之间的依赖性。对象之间的耦合越高，维护成本越高。因此对象的设计应使类和构件之间的耦合最小。软件设计中通常用耦合度和内聚度作为衡量模块独立程度的标准。<strong>划分模块的一个准则就是高内聚低耦合。</strong></p><p><strong>它有如下分类：</strong> （<code>1</code>）内容耦合。当一个模块直接修改或操作另一个模块的数据时，或一个模块不通过正常入口而转入另一个模块时，这样的耦合被称为内容耦合。内容耦合是最高程度的耦合，应该避免使用之。 （<code>2</code>）公共耦合。两个或两个以上的模块共同引用一个全局数据项，这种耦合被称为公共耦合。在具有大量公共耦合的结构中，确定究竟是哪个模块给全局变量赋了一个特定的值是十分困难的。 （<code>3</code>） 外部耦合 。一组模块都访问同一全局简单变量而不是同一全局数据结构，而且不是通过参数表传递该全局变量的信息，则称之为外部耦合。 （<code>4</code>） 控制耦合 。一个模块通过接口向另一个模块传递一个控制信号，接受信号的模块根据信号值而进行适当的动作，这种耦合被称为控制耦合。 （<code>5</code>）标记耦合 。若一个模块 <code>A</code> 通过接口向两个模块 <code>B</code> 和 <code>C</code> 传递一个公共参数，那么称模块 <code>B</code> 和 <code>C</code> 之间存在一个标记耦合。 （<code>6</code>） 数据耦合。模块之间通过参数来传递数据，那么被称为数据耦合。数据耦合是最低的一种耦合形式，系统中一般都存在这种类型的耦合，因为为了完成一些有意义的功能，往往需要将某些模块的输出数据作为另一些模块的输入数据。 （<code>7</code>） 非直接耦合 。两个模块之间没有直接关系，它们之间的联系完全是通过主模块的控制和调用来实现的。</p><p><strong>总结：</strong> 耦合是影响软件复杂程度和设计质量的一个重要因素，在设计上我们应采用以下原则：如果模块间必须存在耦合，就尽量使用数据耦合，少用控制耦合，限制公共耦合的范围，尽量避免使用内容耦合。</p><p><strong>内聚与耦合</strong> 内聚标志一个模块内各个元素彼此结合的紧密程度，它是信息隐蔽和局部化概念的自然扩展。内聚是从功能角度来度量模块内的联系，一个好的内聚模块应当恰好做一件事。它描述的是模块内的功能联系。耦合是软件</p><p>结构中各模块之间相互连接的一种度量，耦合强弱取决于模块间接口的复杂程度、进入或访问一个模块的点以及通过接口的数据。 程序讲究的是低耦合，高内聚。就是同一个模块内的各个元素之间要高度紧密，但是各个模块之间的相互依存度却要不那么紧密。</p><p>内聚和耦合是密切相关的，同其他模块存在高耦合的模块意味着低内聚，而高内聚的模块意味着该模块同其他模块之间是低耦合。在进行软件设计时，应力争做到高内聚，低耦合。￼ 我们在开发中，有些依赖关系是必须的，有些依赖关系可以通过优化代码来解除的。 请看下面的示例代码：</p><p>/** * 账户的业务层实现类</p><ul><li><p>@author 黑马程序员</p></li><li><p>@Company <a href="http://www.ithiema.com" target="_blank" rel="noreferrer">http://www.ithiema.com</a></p></li><li><p>@Version 1.0 */ public class AccountServiceImpl implements IAccountService { private IAccountDao accountDao = new AccountDaoImpl(); } 上面的代码表示： 业务层调用持久层，并且此时业务层在依赖持久层的接口和实现类。如果此时没有持久层实现类，编译将不能通过。这种编译期依赖关系，应该在我们开发中杜绝。我们需要优化代码解决。</p></li></ul><p><strong>再比如：</strong> 早期我们的 <code>JDBC</code> 操作，注册驱动时，我们为什么不使用 <code>DriverManager</code> 的 <code>register</code> 方法，而是采用 <code>Class.forName</code> 的方式？</p><p>public class JdbcDemo1 { /**</p><ul><li><p>@author 黑马程序员</p></li><li><p>@Company <a href="http://www.ithiema.com" target="_blank" rel="noreferrer">http://www.ithiema.com</a></p></li><li><p>@Version 1.0</p></li><li><p>@param args</p></li><li><p>@throws Exception */ public static void main(String[] args) throws Exception { //1. 注册驱动</p></li></ul><p><a href="//DriverManager.registerDriver" target="_blank" rel="noreferrer">//DriverManager.registerDriver</a>(new com.mysql.jdbc.Driver()); Class.forName(&quot;com.mysql.jdbc.Driver&quot;); //2. 获取连接</p><p>//3. 获取预处理 <code>sql</code> 语句对象</p><p>//4. 获取结果集</p><p>//5. 遍历结果集</p><p>} } <strong>原因就是：</strong> 我们的类依赖了数据库的具体驱动类（<code>MySQL</code>），如果这时候更换了数据库品牌（比如 <code>Oracle</code>），需要修改源码来重新数据库驱动。这显然不是我们想要的。</p><p><strong>解决程序耦合的思路</strong> 当是我们讲解 <code>jdbc</code> 时，是通过反射来注册驱动的，代码如下：</p><p>Class.forName(&quot;com.mysql.jdbc.Driver&quot;);// 此处只是一个字符串￼此时的好处是，我们的类中不再依赖具体的驱动类，此时就算删除 <code>mysql</code> 的驱动 <code>jar</code> 包，依然可以编译（运行就不要想了，没有驱动不可能运行成功的）。 同时，也产生了一个新的问题，<code>mysql</code> 驱动的全限定类名字符串是在 <code>java</code> 类中写死的，一旦要改还是要修改源码。 解决这个问题也很简单，使用配置文件配置。</p><p><strong>工厂模式解耦</strong> 在实际开发中我们可以把三层的对象都使用配置文件配置起来，当启动服务器应用加载的时候，让一个类中的方法通过读取配置文件，把这些对象创建出来<strong>并存起来</strong>。在接下来的使用的时候，直接拿过来用就好了。 那么，这个读取配置文件，创建和获取三层对象的类就是工厂。</p><p><strong>控制反转</strong><code>-Inversion Of Control</code> 上一小节解耦的思路有 <code>2</code> 个问题：</p><p><code>1</code></p><p><strong>、存哪去？</strong> 分析：由于我们是很多对象，肯定要找个集合来存。这时候有 <code>Map</code> 和 <code>List</code> 供选择。 到底选 <code>Map</code> 还是 <code>List</code> 就看我们有没有查找需求。有查找需求，选 <code>Map</code>。 所以我们的答案就是在应用加载时，创建一个 <code>Map</code>，用于存放三层对象。 我们把这个 <code>map</code> 称之为<strong>容器</strong>。</p><p><code>2</code><strong>、还是没解释什么是工厂？</strong> 工厂就是负责给我们从容器中获取指定对象的类。这时候我们获取对象的方式发生了改变。 原来： 我们在获取对象时，都是采用 <code>new</code> 的方式。是主动的。 现在： 我们获取对象时，同时跟工厂要，有工厂为我们查找或者创建对象。是被动的。这种被动接收的方式获取对象的思想就是控制反转，它是 <code>spring</code> 框架的核心之一。</p><p><strong>明确</strong> <code>ioc</code> <strong>的作用</strong>： 削减计算机程序的耦合<code>(</code>解除我们代码中的依赖关系<code>)</code>。</p></div>',1)])])}const _=e(d,[["render",p]]);export{m as __pageData,_ as default};
